const input = $input.first().json;

const models = {
  "black-forest-labs/flux-dev": {
    "input":{
        prompt: input.prompt,
        go_fast: true,
        guidance: 3.5,
        megapixels: "1",
        num_outputs: 1,
        aspect_ratio: "16:9",
        output_format: "webp",
        output_quality: 80,
        prompt_strength: 0.8,
        num_inference_steps: 28,
      }
  },
  "black-forest-labs/flux-schnell" : {
    "input": {
      "prompt": input.prompt,
      "go_fast": true,
      "megapixels": "1",
      "num_outputs": 1,
      "aspect_ratio": "16:9",
      "output_format": "webp",
      "output_quality": 80,
      "num_inference_steps": 4
    }
  },
  "black-forest-labs/flux-1.1-pro":{
    "input": {
      "prompt": input.prompt,
      "aspect_ratio": "16:9",
      "output_format": "webp",
      "output_quality": 100,
      "safety_tolerance": 2,
      "prompt_upsampling": true
    }
  }
  // You can define more models here
};

if (!models.hasOwnProperty(input.model)) {
  throw new Error(`Model "${input.model}" is not supported.`);
}

return {
  ...input,
  model: input.model,
  model_config: models[input.model],
};
